from pathlib import Path
import base64, gzip, sys

root = Path(sys.argv[1]).resolve()

FILES = {
    'frontend/src/img/species-img.tsx': '',
    'PKVault.Core/static-data/routes/StaticDataRoute.cs': '',
    'PKVault.Core/router/RouteJsonContext.cs': '',
}

for rel, payload in FILES.items():
    path = root / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(gzip.decompress(base64.b64decode(payload)))

species = (root / 'frontend/src/img/species-img.tsx').read_text(encoding='utf-8')
route = (root / 'PKVault.Core/static-data/routes/StaticDataRoute.cs').read_text(encoding='utf-8')
ctx = (root / 'PKVault.Core/router/RouteJsonContext.cs').read_text(encoding='utf-8')
assert '/api/StaticData/gen1-glitch-sprite' in species
assert 'normalizeGen1GlitchSprite' in species
assert 'RBGlitchName${hex}.png' in species
assert 'crashGlitchSprite' not in species
assert 'archives.bulbagarden.net/media/upload' not in species
assert 'Gen1GlitchSpriteDTO' in route
assert 'cdn.bulbagarden.net/upload' in route
assert '[JsonSerializable(typeof(Gen1GlitchSpriteDTO))]' in ctx
print('PKVault V8 alpha52w Gen-I glitch sprite proxy/normalizer patch applied')
